from playwright.sync_api import sync_playwright

JS = """() => {
  const res = {};
  const m = document.querySelector('div.queue-list');
  if (!m) { res.err = 'no marker'; return res; }
  const chain = (el, n) => {
    const out = [];
    let q = el;
    for (let i = 0; i < n && q; i++) {
      q = q.parentElement;
      if (!q) break;
      out.push(q.tagName.toLowerCase() + ' | testid=' + (q.getAttribute('data-testid') || '-') + ' | class=' + String(q.className).slice(0, 70));
    }
    return out;
  };
  res.markerChain = chain(m, 5);
  const btn = document.querySelector("div[data-testid='stButton'] button");
  res.btnChain = btn ? chain(btn, 5) : ['none'];
  // is the marker's container a previous sibling of the button's container?
  const mc = m.closest("div[data-testid='stElementContainer']") || m.parentElement;
  const bc = btn ? (btn.closest("div[data-testid='stElementContainer']") || btn.parentElement) : null;
  res.sameParent = !!(mc && bc && mc.parentElement === bc.parentElement);
  res.markerContainerTestid = mc ? (mc.getAttribute('data-testid') || '-') : '-';
  res.btnContainerTestid = bc ? (bc.getAttribute('data-testid') || '-') : '-';
  return res;
}"""

with sync_playwright() as p:
    b = p.chromium.launch()
    pg = b.new_page(viewport={"width": 1680, "height": 1000})
    pg.goto("http://localhost:8752/", wait_until="networkidle", timeout=90000)
    pg.wait_for_timeout(15000)
    import json
    print(json.dumps(pg.evaluate(JS), indent=2))
    b.close()

