import json
import sys

from playwright.sync_api import sync_playwright

PORT = sys.argv[1] if len(sys.argv) > 1 else "8753"
OUT = sys.argv[2] if len(sys.argv) > 2 else "after.png"

PROBE = """() => {
  const rows = document.querySelectorAll('div[class*="st-key-qrow-"]');
  if (!rows.length) return {err: 'no qrow containers'};
  const btn = rows[0].querySelector('button');
  const c = getComputedStyle(btn);
  const r = btn.getBoundingClientRect();
  const sel = document.querySelectorAll('div[class*="st-key-qrow-sel-"]');
  let selStyle = null;
  if (sel.length) {
    const sb = sel[0].querySelector('button');
    const sc = getComputedStyle(sb);
    selStyle = {bg: sc.backgroundColor, shadow: sc.boxShadow.slice(0, 40)};
  }
  return {
    nRows: rows.length,
    textAlign: c.textAlign,
    padding: c.padding,
    borderBottom: c.borderBottomWidth + ' ' + c.borderBottomStyle,
    rowHeight: Math.round(r.height),
    fontWeight: c.fontWeight,
    nChips: document.querySelectorAll('span.chip').length,
    nSelected: sel.length,
    selStyle: selStyle,
    exception: !!document.querySelector("div[data-testid='stException']"),
  };
}"""

with sync_playwright() as p:
    b = p.chromium.launch()
    pg = b.new_page(viewport={"width": 1680, "height": 1000})
    errs = []
    pg.on("pageerror", lambda e: errs.append(str(e)))
    pg.goto(f"http://localhost:{PORT}/", wait_until="networkidle", timeout=90000)
    pg.wait_for_timeout(18000)
    for _ in range(20):
        if pg.query_selector('div[class*="st-key-qrow-"]'):
            break
        pg.wait_for_timeout(2000)
    pg.wait_for_timeout(2000)

    print("BEFORE CLICK:", json.dumps(pg.evaluate(PROBE), indent=2))
    if pg.query_selector("div[data-testid='stException']"):
        print("EXC:", pg.inner_text("div[data-testid='stException']")[:800])

    # click the third row and confirm a selected state appears
    rows = pg.query_selector_all('div[class*="st-key-qrow-"] button')
    if len(rows) > 2:
        rows[2].click()
        pg.wait_for_timeout(9000)
        print("AFTER CLICK:", json.dumps(pg.evaluate(PROBE), indent=2))

    pg.screenshot(path=OUT, full_page=False)
    print("page errors:", errs[:2])
    print("saved", OUT)
    b.close()

