/* Line one is the subject, line two the status and sender. The label is a single
   markdown paragraph with a hard break, so the second line is targeted through
   its <br> rather than as a separate node. */
div[class*="st-key-qrow-"] button p br { line-height: 0; }

/* The status line: smaller and quieter than the subject, and tinted by outcome so
   the queue can be read down its left edge. The tint is applied per row through
   a modifier class on the key -- see ``_queue_row``. */
div[class*="st-key-qrow-"] button p {
    font-size: 0.78rem !important;
    color: inherit;
}
div[class*="qrow-esc-"] button p { --status: #b26a00; }
div[class*="qrow-aut-"] button p { --status: #1a7a4c; }
div[class*="qrow-red-"] button p { --status: #4a55b8; }

