import json
import sys

from playwright.sync_api import sync_playwright

PORT = sys.argv[1]

JS = """() => {
  const row = document.querySelector('div[class*="st-key-qrow-"]');
  const btn = row.querySelector('button');
  const out = [];
  let el = btn;
  for (let i = 0; i < 4 && el; i++) {
    const c = getComputedStyle(el);
    out.push({
      tag: el.tagName.toLowerCase(),
      testid: el.getAttribute('data-testid') || '-',
      display: c.display,
      justify: c.justifyContent,
      align: c.alignItems,
      textAlign: c.textAlign,
      width: Math.round(el.getBoundingClientRect().width),
    });
    el = el.firstElementChild;
  }
  return out;
}"""

with sync_playwright() as p:
    b = p.chromium.launch()
    pg = b.new_page(viewport={"width": 1680, "height": 1050})
    pg.goto(f"http://localhost:{PORT}/", wait_until="networkidle", timeout=90000)
    for _ in range(30):
        if pg.query_selector('div[class*="st-key-qrow-"]'):
            break
        pg.wait_for_timeout(2000)
    pg.wait_for_timeout(3000)
    print(json.dumps(pg.evaluate(JS), indent=2))
    b.close()

